begin;
with j as (select * from jsonb_to_recordset($law7d0054$[{"code_id":"NK_RF","article_number":"129.5","version_date":"2000-07-31","article_text":"Неуплата или неполная уплата контролирующим лицом, являющимся налогоплательщиком - физическим лицом или организацией, сумм налога в результате невключения в налоговую базу доли прибыли контролируемой иностранной компании\n\nвлечет взыскание штрафа в размере 20 процентов от суммы неуплаченного налога в отношении прибыли контролируемой иностранной компании, подлежащей включению в налоговую базу по налогу на доходы физических лиц для контролирующих лиц, являющихся налогоплательщиками - физическими лицами, налоговую базу по налогу на прибыль организаций для контролирующих лиц, являющихся налогоплательщиками - организациями, но не менее 100 000 рублей.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 129.5. Неуплата или неполная уплата сумм налога в результате невключения в налоговую базу доли прибыли контролируемой иностранной компании","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ad5064105af2cf6a8cf8a7d9e9400543d197b23ad9cd09a7de6f96b32790416"},{"code_id":"NK_RF","article_number":"129.6","version_date":"2000-07-31","article_text":"1. Неправомерное непредставление в установленный срок контролирующим лицом в налоговый орган уведомления о контролируемых иностранных компаниях за календарный год или представление контролирующим лицом в налоговый орган уведомления о контролируемых иностранных компаниях, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 500 000 рублей по каждой контролируемой иностранной компании, сведения о которой не представлены либо в отношении которой представлены недостоверные сведения. (В редакции Федерального закона от 09.11.2020 № 368-ФЗ)\n\n2. Неправомерное непредставление в установленный срок налогоплательщиком в налоговый орган уведомления об участии в иностранных организациях или представление уведомления об участии в иностранных организациях, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 50 000 рублей в отношении каждой иностранной организации, сведения о которой не представлены либо в отношении которой представлены недостоверные сведения.\n\n(Дополнение статьей - Федеральный закон от 24.11.2014 № 376-ФЗ)","article_title":"Статья 129.6. Неправомерное непредставление уведомления о контролируемых иностранных компаниях, уведомления об участии в иностранных организациях, представление недостоверных сведений в уведомлении о контролируемых иностранных компаниях, уведомлении об участии в иностранных организациях","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2dcafaa185a16d34c36406f374c95b68e4596f2684758302b13f2b28c7b2bc83"},{"code_id":"NK_RF","article_number":"129.7","version_date":"2000-07-31","article_text":"1. Непредставление в установленный срок организацией финансового рынка информации, предусмотренной пунктом 1 статьи 1422 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 300 000 рублей.\n\n2. Невключение организацией финансового рынка информации в отношении отдельного клиента, выгодоприобретателя и (или) лиц, прямо или косвенно их контролирующих, предусмотренной абзацем первым пункта 1 статьи 1422 настоящего Кодекса, в состав информации, представляемой в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов,\n\nвлечет взыскание штрафа в размере 50 000 рублей за каждый факт такого нарушения.\n\n3. Представление организацией финансового рынка неполной или недостоверной информации, предусмотренной абзацем первым пункта 1 статьи 1422 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 25 000 рублей за каждый факт такого нарушения.\n\n4. Деяние, предусмотренное пунктом 2 или 3 настоящей статьи, совершенное умышленно (в том числе в результате нарушения запретов, установленных пунктом 21 статьи 1422 и пунктом 21 статьи 1424 настоящего Кодекса),\n\nвлечет взыскание штрафа в размере 100 000 рублей за каждый факт такого нарушения.\n\n5. Организация финансового рынка освобождается от ответственности, предусмотренной пунктами 2 и 3 настоящей статьи, если совершение ею налогового правонарушения обусловлено совершением клиентом организации финансового рынка деяния, предусмотренного статьей 1297-1 настоящего Кодекса. Положения настоящего пункта применяются при отсутствии признаков налогового правонарушения, предусмотренного статьей 1298 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ) (В редакции Федерального закона от 29.11.2021 № 380-ФЗ)","article_title":"Статья 129.7. Непредставление (невключение) организацией финансового рынка информации либо представление ею неполной или недостоверной информации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69d4ad91c9ba271a2b54de7a19d1982b1793c617f7b0651eddb16c46a5b92fdf"},{"code_id":"NK_RF","article_number":"129.7-1","version_date":"2000-07-31","article_text":"1. Представление клиентом организации финансового рынка неполной или недостоверной информации в отношении самого себя, выгодоприобретателя и (или) лиц, прямо или косвенно их контролирующих, запрашиваемой организацией финансового рынка в соответствии со статьей 1424 настоящего Кодекса,\n\nвлечет взыскание штрафа с клиента организации финансового рынка - физического лица в размере 10 000 рублей, с клиента организации финансового рынка - юридического лица в размере 25 000 рублей за каждый факт такого нарушения в отношении каждого заключенного между клиентом и организацией финансового рынка договора, предусматривающего оказание финансовых услуг.\n\n2. Деяние, предусмотренное пунктом 1 настоящей статьи, совершенное умышленно,\n\nвлечет взыскание штрафа с клиента организации финансового рынка - физического лица в размере 20 000 рублей, с клиента организации финансового рынка - юридического лица в размере 50 000 рублей за каждый факт такого нарушения в отношении каждого заключенного между клиентом и организацией финансового рынка договора, предусматривающего оказание финансовых услуг.\n\n(Дополнение статьей - Федеральный закон от 29.11.2021 № 380-ФЗ)","article_title":"Статья 129.7-1. Представление клиентом организации финансового рынка неполной или недостоверной информации, запрашиваемой организацией финансового рынка","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"728b04f7520b6bd2291a13e18d417942b279651a10a76075ad5da751028c7bc1"},{"code_id":"NK_RF","article_number":"129.8","version_date":"2000-07-31","article_text":"Нарушение организацией финансового рынка порядка установления налогового резидентства клиентов организации финансового рынка, выгодоприобретателей и лиц, прямо или косвенно их контролирующих, путем непринятия мер, установленных статьей 1424 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 50 000 рублей за непринятие мер в отношении каждого клиента, выгодоприобретателя либо лица, прямо или косвенно их контролирующего.\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 129.8. Нарушение организацией финансового рынка порядка установления налогового резидентства клиентов организаций финансового рынка, выгодоприобретателей и лиц, прямо или косвенно их контролирующих","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c19a447cccd87f8c78c07b0450bd24f8087e8cc8fb24acf2e425f6d3206c1de0"},{"code_id":"NK_RF","article_number":"129.9","version_date":"2000-07-31","article_text":"Неправомерное непредставление в установленный срок уведомления об участии в международной группе компаний или представление уведомления об участии в международной группе компаний, содержащего недостоверные сведения,\n\nвлечет взыскание штрафа в размере 500 000 рублей за каждый факт такого нарушения. (В редакции  Федерального закона от 27.11.2023 № 539-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 129.9. Непредставление уведомления об участии в международной группе компаний, представление уведомления об участии в международной группе компаний, содержащего недостоверные сведения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"41a836b2e48bf3a8f0b38c147e7e0fac73d952b4c8680b3e3499f987cfa9ebb3"},{"code_id":"NK_RF","article_number":"13","version_date":"2000-07-31","article_text":"К федеральным налогам и сборам относятся:\n\n1) налог на добавленную стоимость;\n\n2) акцизы;\n\n3) налог на доходы физических лиц;\n\n4) (Пункт утратил силу - Федеральный закон от 24.07.2009 № 213-ФЗ)\n\n5) налог на прибыль организаций;\n\n6) налог на добычу полезных ископаемых;\n\n7) (Пункт утратил силу - Федеральный закон от 01.07.2005 № 78-ФЗ)\n\n8) водный налог;\n\n9) сборы за пользование объектами животного мира и за пользование объектами водных биологических ресурсов;\n\n10) государственная пошлина;\n\n11) налог на дополнительный доход от добычи углеводородного сырья; (Дополнение пунктом - Федеральный закон от 19.07.2018 № 199-ФЗ)\n\n12) налог на сверхприбыль. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 415-ФЗ)\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)","article_title":"Статья 13. Федеральные налоги и сборы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edf2611947f417c598339145075fbc29a579f6a2c9129ec95b1f0e2d800651f0"},{"code_id":"NK_RF","article_number":"135.3","version_date":"2000-07-31","article_text":"1. Представление банком налоговому органу недостоверных сведений о фактически произведенных налогоплательщиком расходах на новое строительство либо приобретение на территории Российской Федерации одного или нескольких объектов недвижимого имущества, указанных в подпункте 3 пункта 1 статьи 220 настоящего Кодекса, и (или) на погашение процентов, предусмотренных подпунктом 4 пункта 1 статьи 220 настоящего Кодекса, в рамках процедуры получения налогоплательщиком имущественных налоговых вычетов в порядке, установленном статьей 2211 настоящего Кодекса,\n\nвлечет взыскание штрафа в размере 20 процентов от суммы налога, неправомерно полученного налогоплательщиком в связи с предоставлением имущественного налогового вычета в упрощенном порядке на основании представленных банком недостоверных сведений.\n\n2. Банк освобождается от ответственности, предусмотренной пунктом 1 настоящей статьи, в случае, если им самостоятельно выявлены ошибки и уточненные сведения представлены налоговому органу до момента, когда банк узнал об обнаружении налоговым органом недостоверности представленных банком сведений.\n\n(Дополнение статьей - Федеральный закон от 20.04.2021 № 100-ФЗ)","article_title":"Статья 135.3. Представление банком налоговому органу недостоверных сведений в рамках процедуры получения налогоплательщиками имущественных налоговых вычетов в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aa6462ef131585d0de99e5bf5bb7aad92273aadf35a24186c444cacd1fc92c6f"},{"code_id":"NK_RF","article_number":"135.4","version_date":"2000-07-31","article_text":"Непредставление банком, находящимся на территории Российской Федерации, либо Центральным банком Российской Федерации, либо государственной корпорацией \"Агентство по страхованию вкладов\" в отношении банков (в случае, если указанная государственная корпорация осуществляет функции временной администрации или полномочия конкурсного управляющего (ликвидатора) банка) налоговому органу в установленный срок информации о суммах выплаченных процентов по вкладам (остаткам на счетах), предусмотренной статьей 2142 настоящего Кодекса, в отношении каждого физического лица\n\nвлечет взыскание штрафа в размере 1000 рублей за каждый случай непредставления информации в отношении физического лица в установленный срок.\n\n(Дополнение статьей - Федеральный закон от 08.08.2024 № 259-ФЗ)","article_title":"Статья 135.4. Непредставление банком, находящимся на территории Российской Федерации, либо Центральным банком Российской Федерации, либо государственной корпорацией \"Агентство по страхованию вкладов\" в отношении банков (в случае, если указанная государственная корпорация осуществляет функции временной администрации или полномочия конкурсного управляющего (ликвидатора) банка) информации о суммах выплаченных процентов по вкладам (остаткам на счетах)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f40fb04ef5ccdc9991b85c0baae3f2977d8b4456cc2649f059fabaa6a924bd39"},{"code_id":"NK_RF","article_number":"136","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 19.12.2023 № 610-ФЗ)\n\nШтрафы, указанные в статьях 132 - 1353, взыскиваются в порядке, аналогичном предусмотренному настоящим Кодексом порядку взыскания санкций за налоговые правонарушения. (В редакции Федерального закона от 20.04.2021 № 100-ФЗ)\n\n(Статья в редакции Федерального закона от 27.06.2011 № 162-ФЗ)","article_title":"Статья 136. Порядок взыскания с банков, оператора платформы цифрового рубля штрафов и пеней","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"545f081c3d8f5843ed4a6f4ac1f06bd46542700c23ae64dc676761827ea07b6c"},{"code_id":"NK_RF","article_number":"137","version_date":"2000-07-31","article_text":"Каждое лицо имеет право обжаловать акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц, если, по мнению этого лица, такие акты, действия или бездействие нарушают его права. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 27.07.2006 № 137-ФЗ; от 23.07.2013 № 248-ФЗ)\n\nНормативные правовые акты налоговых органов могут быть обжалованы в порядке, предусмотренном федеральным законодательством.","article_title":"Статья 137. Право на обжалование","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"af46bfa9868c5922bffa207c8f1828a0fe860dc01a898a4c21e358e184ab5b0f"},{"code_id":"NK_RF","article_number":"138","version_date":"2000-07-31","article_text":"1. Акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц могут быть обжалованы в вышестоящий налоговый орган и (или) в суд в порядке, предусмотренном настоящим Кодексом и соответствующим процессуальным законодательством Российской Федерации.\n\nЖалобой признается обращение лица в налоговый орган, предметом которого является обжалование вступивших в силу актов налогового органа ненормативного характера, действий или бездействия его должностных лиц, если, по мнению этого лица, обжалуемые акты, действия или бездействие должностных лиц налогового органа нарушают его права.\n\nАпелляционной жалобой признается обращение лица в налоговый орган, предметом которого является обжалование не вступившего в силу решения налогового органа о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения, вынесенного в соответствии со статьей 101 настоящего Кодекса, если, по мнению этого лица, обжалуемое решение нарушает его права.\n\n2. Акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц (за исключением актов ненормативного характера, принятых по итогам рассмотрения жалоб, апелляционных жалоб, актов ненормативного характера федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, действий или бездействия его должностных лиц) могут быть обжалованы в судебном порядке только после их обжалования в вышестоящий налоговый орган в порядке, предусмотренном настоящим Кодексом.\n\nВ случае, если решение по жалобе (апелляционной жалобе) не принято вышестоящим налоговым органом в сроки, установленные пунктом 6 статьи 140 настоящего Кодекса, акты налоговых органов ненормативного характера, действия или бездействие их должностных лиц могут быть обжалованы в судебном порядке.\n\nАкты налоговых органов ненормативного характера, принятые по итогам рассмотрения жалоб (апелляционных жалоб), могут быть обжалованы в вышестоящий налоговый орган и (или) в судебном порядке.\n\nАкты ненормативного характера федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, действия или бездействие его должностных лиц обжалуются в судебном порядке.\n\nИсковое заявление, содержащее требование имущественного характера, возникшее в результате реализации актов налоговых органов (за исключением федерального органа исполнительной власти, уполномоченного по контролю и надзору в сфере налогов и сборов) ненормативного характера, в результате действий или бездействия их должностных лиц, может быть подано в суд только после обжалования указанных актов, действий или бездействия в вышестоящий налоговый орган в порядке, предусмотренном настоящим Кодексом. (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\n3. В случае обжалования в судебном порядке актов налоговых органов ненормативного характера, действий или бездействия их должностных лиц (за исключением актов ненормативного характера, принятых по итогам рассмотрения жалоб, апелляционных жалоб, актов ненормативного характера федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, действий или бездействия его должностных лиц) срок для обращения в суд исчисляется со дня, когда лицу стало известно о принятом вышестоящим налоговым органом решении по соответствующей жалобе, или со дня истечения срока принятия решения по жалобе (апелляционной жалобе), установленного пунктом 6 статьи 140 настоящего Кодекса.\n\n4. Обжалование организациями и физическими лицами в судебном порядке актов (в том числе нормативных) налоговых органов, действий или бездействия их должностных лиц производится в порядке, предусмотренном соответствующим процессуальным законодательством Российской Федерации.\n\nВ случае обжалования в судебном порядке актов налоговых органов, действий их должностных лиц исполнение обжалуемых актов, совершение обжалуемых действий могут быть приостановлены судом в порядке, предусмотренном соответствующим процессуальным законодательством Российской Федерации.\n\nЗаявление о приостановлении исполнения обжалуемого решения полностью или частично подается одновременно с жалобой на вступившее в силу решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган, вынесший обжалуемое решение, обязан в течение трех дней со дня поступления банковской гарантии уведомить о данном факте вышестоящий налоговый орган, рассматривающий жалобу. Требования к банковской гарантии и порядок ее представления гарантом устанавливаются в соответствии со статьей 741 настоящего Кодекса с учетом следующих особенностей: (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nсрок действия банковской гарантии должен истекать не ранее чем через шесть месяцев со дня подачи лицом заявления о приостановлении исполнения обжалуемого решения; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nсумма, на которую выдана банковская гарантия, должна обеспечивать исполнение гарантом обязанности по уплате денежной суммы, указанной в заявлении о приостановлении исполнения обжалуемого решения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВышестоящий налоговый орган, рассматривающий жалобу, в течение пяти дней со дня получения заявления о приостановлении исполнения обжалуемого решения полностью или частично принимает одно из следующих решений: (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nо приостановлении исполнения полностью решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения; (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nо приостановлении частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения и (или) об отказе в приостановлении частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения либо о приостановлении частично исполнения решения об отказе в привлечении к ответственности за совершение налогового правонарушения и (или) об отказе в приостановлении частично исполнения решения об отказе в привлечении к ответственности за совершение налогового правонарушения; (Дополнение абзацем - Федеральный закон от 31.07.2023 № 389-ФЗ)\n\nоб отказе в приостановлении исполнения полностью решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nОснованием для принятия решения об отказе в приостановлении полностью или частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения является несоответствие банковской гарантии требованиям, установленным настоящей статьей и статьей 741 настоящего Кодекса. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nО принятом решении в течение трех дней со дня его принятия налоговый орган сообщает в письменной форме лицу, подавшему жалобу. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nРешение о приостановлении полностью или частично исполнения решения о привлечении к ответственности за совершение налогового правонарушения или решения об отказе в привлечении к ответственности за совершение налогового правонарушения действует до дня принятия вышестоящим налоговым органом решения по жалобе. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае неисполнения (неполного исполнения) обязанности по уплате денежной суммы по обжалуемому решению, обеспеченной банковской гарантией, лицом, подавшим жалобу, налоговый орган в срок не позднее пяти дней со дня принятия вышестоящим налоговым органом решения по жалобе направляет гаранту требование об уплате денежной суммы по банковской гарантии в части суммы налога, сбора, страховых взносов, пеней, штрафа, не уплаченной на день принятия вышестоящим налоговым органом решения по жалобе. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nНалоговый орган, вынесший обжалуемое решение, в соответствии со статьей 741 настоящего Кодекса уведомляет гаранта, выдавшего банковскую гарантию, о его освобождении от обязательств по этой гарантии в срок не позднее пяти дней со дня исполнения лицом, подавшим жалобу, обязанности по уплате суммы налога, сбора, страховых взносов, пеней, штрафа, которая была обеспечена такой банковской гарантией, либо не позднее пяти дней со дня принятия решения по жалобе, в соответствии с которым у лица, подавшего жалобу, отсутствует обязанность по уплате суммы налога, сбора, страховых взносов, пеней, штрафа, обеспеченная такой банковской гарантией. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n52. В случае подачи физическим лицом, не являющимся индивидуальным предпринимателем, жалобы исполнение обжалуемого решения о привлечении к ответственности за совершение налогового правонарушения (решения об отказе в привлечении к ответственности за совершение налогового правонарушения), решения об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично приостанавливается в части обжалуемых сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы, до даты вступления в законную силу судебного акта о взыскании таких сумм.\n\nВ случае подачи физическим лицом, не являющимся индивидуальным предпринимателем, жалобы на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении, исполнение обязанности налогоплательщика по уплате налога, указанного в налоговом уведомлении, приостанавливается в части обжалуемых сумм налогов, обязанность по уплате которых не исполнена по состоянию на дату получения налоговым органом жалобы, до даты истечения тридцати дней со дня принятия решения вышестоящего налогового органа об оставлении данной жалобы без удовлетворения (если в течение указанного тридцатидневного срока не было представлено уведомление о несогласии с решением вышестоящего налогового органа по жалобе на действия налогового органа по исчислению суммы соответствующего налога, указанной в налоговом уведомлении) или до даты вступления в законную силу судебного акта о взыскании таких сумм (если в течение указанного тридцатидневного срока такое уведомление было представлено) либо до принятия решения об оставлении жалобы без рассмотрения.\n\nВ случае подачи физическим лицом, не являющимся индивидуальным предпринимателем, жалобы на требование об уплате задолженности, на решение о взыскании задолженности исполнение обжалуемого акта налогового органа ненормативного характера приостанавливается в части обжалуемых сумм налогов, сборов, страховых взносов, пеней, штрафов, процентов, которые указаны в решении о привлечении к ответственности за совершение налогового правонарушения (решении об отказе в привлечении к ответственности за совершение налогового правонарушения), решении об отмене (полностью или частично) решения о предоставлении налогового вычета полностью или частично и (или) в налоговом уведомлении, обязанность по уплате которых не исполнена по состоянию на дату поступления в налоговый орган жалобы и в отношении которых отсутствует судебный акт о взыскании задолженности, до истечения пятнадцати дней со дня принятия решения по соответствующей жалобе.\n\n(Дополнение пунктом - Федеральный закон от 31.07.2025 № 287-ФЗ)\n\nОтзыв жалобы (апелляционной жалобы) лишает лицо, подавшее соответствующую жалобу, права на повторное обращение с жалобой (апелляционной жалобой) по тем же основаниям и в том же порядке. (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n(Статья в редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 138. Порядок обжалования","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a4c29367521f32bd360a16deede2f3afa0051aca9f8f5edc410f1834955ed272"},{"code_id":"NK_RF","article_number":"139","version_date":"2000-07-31","article_text":"1. Жалоба подается в вышестоящий налоговый орган через налоговый орган, акты ненормативного характера, действия или бездействие должностных лиц которого обжалуются. Налоговый орган, акты ненормативного характера, действия или бездействие должностных лиц которого обжалуются, обяз\n\nан в течение трех дней со дня поступления такой жалобы направить ее со всеми материалами в вышестоящий налоговый орган.\n\n2. Жалоба в вышестоящий налоговый орган может быть подана, если иное не установлено настоящим Кодексом, в течение одного года со дня, когда лицо узнало или должно было узнать о нарушении своих прав.\n\nЖалоба на вступившее в силу решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения, которое не было обжаловано в апелляционном порядке, может быть подана в течение одного года со дня вынесения обжалуемого решения.\n\nЖалоба в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, может быть подана в течение трех месяцев со дня принятия вышестоящим налоговым органом решения по жалобе (апелляционной жалобе).\n\nВ случае пропуска по уважительной причине срока подачи жалобы этот срок по ходатайству лица, подающего жалобу, может быть восстановлен вышестоящим налоговым органом.\n\n3. Вступившее в силу решение налогового органа, вынесенное по результатам рассмотрения материалов налоговой проверки консолидированной группы налогоплательщиков и не обжалованное в апелляционном порядке, может быть обжаловано ответственным участником этой группы либо самостоятельно иным участником этой группы в части привлечения такого участника к ответственности за совершение налогового правонарушения. Такая жалоба может быть подана в течение одного года со дня вынесения обжалуемого решения.\n\n(Статья в редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139. Порядок и сроки подачи жалобы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d9dcad5d1247a8156b4c8daefc25ffac0d10760f865417463ae7e9c68c07ec5"},{"code_id":"NK_RF","article_number":"139.1","version_date":"2000-07-31","article_text":"1. Апелляционная жалоба на решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения подается через вынесший соответствующее решение налоговый орган. Налоговый орган, решение которого обжалуется, обязан в течение трех дней со дня поступления такой жалобы направить ее со всеми материалами в вышестоящий налоговый орган.\n\n2. Апелляционная жалоба на решение о привлечении к ответственности за совершение налогового правонарушения или решение об отказе в привлечении к ответственности за совершение налогового правонарушения в вышестоящий налоговый орган может быть подана до дня вступления в силу обжалуемого решения.\n\n3. Апелляционная жалоба на решение налогового органа, вынесенное по результатам рассмотрения материалов налоговой проверки консолидированной группы налогоплательщиков, может быть подана до дня вступления в силу обжалуемого решения ответственным участником этой группы либо самостоятельно иным участником этой группы в части привлечения такого участника к ответственности за совершение налогового правонарушения.\n\n4. Не могут быть обжалованы в апелляционном порядке решение о привлечении к ответственности за совершение налогового правонарушения и решение об отказе в привлечении к ответственности за совершение налогового правонарушения, вынесенные федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139.1. Порядок и сроки подачи апелляционной жалобы","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9f90efc1818aa7ce4364888d9008d1145b17c8941dbe4ca9991431cc494ef456"},{"code_id":"NK_RF","article_number":"139.2","version_date":"2000-07-31","article_text":"1. Жалоба подается в письменной форме. Жалоба подписывается лицом, ее подавшим, или его представителем.\n\nЖалоба может быть направлена в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\nФорматы и порядок представления жалобы в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n2. В жалобе указываются:\n\n1) фамилия, имя, отчество и место жительства физического лица, подающего жалобу, или наименование и адрес организации, подающей жалобу;\n\n2) обжалуемые акт налогового органа ненормативного характера, действия или бездействие его должностных лиц;\n\n3) наименование налогового органа, акт ненормативного характера которого, действия или бездействие должностных лиц которого обжалуются;\n\n4) основания, по которым лицо, подающее жалобу, считает, что его права нарушены;\n\n5) требования лица, подающего жалобу;\n\n6) способ получения решения по жалобе: на бумажном носителе, в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n3. В жалобе могут быть указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для своевременного рассмотрения жалобы сведения.\n\n4. В случае подачи жалобы уполномоченным представителем лица, обжалующего акт налогового органа ненормативного характера, действия или бездействие его должностных лиц, к жалобе прилагаются документы, подтверждающие полномочия этого представителя.\n\n5. К жалобе могут быть приложены документы, подтверждающие доводы лица, подающего жалобу.\n\n6. Положения настоящей статьи применяются также к апелляционной жалобе.\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139.2. Форма и содержание жалобы (апелляционной жалобы)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f35779a7fcaab968d7db319cb35bc929be68cf15f4180c338aa050456e0ebba0"},{"code_id":"NK_RF","article_number":"139.3","version_date":"2000-07-31","article_text":"1. Вышестоящий налоговый орган оставляет без рассмотрения жалобу полностью или в части, если установит, что:\n\n1) жалоба подана с нарушением порядка, установленного пунктом 1 статьи 1392 настоящего Кодекса, или в жалобе не указаны акты налогового органа ненормативного характера, действия или бездействие его должностных лиц, которые привели к нарушению прав лица, подавшего жалобу; (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n2) жалоба подана после истечения срока подачи жалобы, установленного настоящим Кодексом, и не содержит ходатайства о его восстановлении или в восстановлении пропущенного срока на подачу жалобы отказано;\n\n3) до принятия решения по жалобе от лица, ее подавшего, поступило заявление об отзыве жалобы полностью или в части;\n\n4) ранее подана жалоба по тем же основаниям, за исключением случая, если после ее рассмотрения разрешен спор о том же предмете и по тем же основаниям в порядке, предусмотренном главой 203 настоящего Кодекса; (В редакции Федерального закона от 17.02.2021 № 6-ФЗ)\n\n5) до принятия решения по жалобе налоговый орган сообщил об устранении нарушения прав лица, подавшего жалобу, в порядке, установленном пунктом 11 статьи 139 настоящего Кодекса; (Дополнение подпунктом - Федеральный закон от 01.05.2016 № 130-ФЗ)\n\n6) до принятия решения по жалобе налоговый спор о том же предмете и по тем же основаниям был разрешен судом; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n7) жалоба не подписана лицом, подавшим жалобу, или его представителем либо не представлены оформленные в установленном порядке документы, подтверждающие полномочия представителя лица на ее подписание; (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n8) до принятия решения по жалобе организация, подавшая жалобу, исключена из Единого государственного реестра юридических лиц по решению регистрирующего органа или ликвидирована либо получены сведения о смерти или об объявлении умершим физического лица, подавшего жалобу, и при этом спорное правоотношение не допускает правопреемства. (Дополнение подпунктом - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nВ случае, предусмотренном подпунктом 5 пункта 1 настоящей статьи, налоговый орган, рассматривающий жалобу, принимает решение об оставлении жалобы без рассмотрения полностью или в части в течение пяти дней со дня получения информации или документов об устранении нарушения прав лица, подавшего жалобу.\n\nВ случаях, предусмотренных подпунктами 6 и 8 пункта 1 настоящей статьи, налоговый орган, рассматривающий жалобу, принимает решение об оставлении жалобы без рассмотрения полностью или в части в течение пяти дней со дня получения информации о наличии указанных в данных подпунктах обстоятельств. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nРешение об оставлении жалобы без рассмотрения вручается или направляется лицу, подавшему жалобу, в течение трех дней со дня его принятия.\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 139.3. Оставление жалобы (апелляционной жалобы) без рассмотрения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"26db0d7d130e178ce71eee80fbd817f68aac9e5c4fb68c8fa59df221e13745f4"},{"code_id":"NK_RF","article_number":"14","version_date":"2000-07-31","article_text":"К региональным налогам относятся:\n\n1) налог на имущество организаций;\n\n2) налог на игорный бизнес;\n\n3) транспортный налог.\n\n(Статья в редакции Федерального закона от 29.07.2004 № 95-ФЗ)","article_title":"Статья 14. Региональные налоги","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71fe4bfcd1ee742e041374e0f47b9664707f498cb02c4231f8c416f1236816de"},{"code_id":"NK_RF","article_number":"140","version_date":"2000-07-31","article_text":"1. В ходе рассмотрения жалобы (апелляционной жалобы) лицо, подавшее эту жалобу, до принятия по ней решения вправе представить дополнительные документы, подтверждающие его доводы.\n\nЛицо, подавшее жалобу (апелляционную жалобу), до принятия по ней решения вправе обратиться с ходатайством о приостановлении рассмотрения жалобы (апелляционной жалобы) полностью или в части в целях представления дополнительных документов (информации), но не более чем на шесть месяцев. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nВ течение пяти дней со дня получения указанного ходатайства вышестоящий налоговый орган, рассматривающий жалобу (апелляционную жалобу), принимает одно из следующих решений: (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nо приостановлении рассмотрения жалобы (апелляционной жалобы) полностью или в части; (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nоб отказе в приостановлении рассмотрения жалобы (апелляционной жалобы). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nО принятом решении в течение трех дней со дня его принятия сообщается лицу, подавшему жалобу (апелляционную жалобу). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n2. Вышестоящий налоговый орган рассматривает жалобу (апелляционную жалобу), документы, подтверждающие доводы лица, подавшего жалобу (апелляционную жалобу), дополнительные документы, представленные в ходе рассмотрения жалобы (апелляционной жалобы), а также материалы, представленные нижестоящим налоговым органом, без участия лица, подавшего жалобу (апелляционную жалобу), за исключением случаев, предусмотренных настоящим пунктом.\n\nВ случае выявления в ходе рассмотрения жалобы (апелляционной жалобы) на решение о привлечении к ответственности за совершение налогового правонарушения или на решение об отказе в привлечении к ответственности за совершение налогового правонарушения противоречий между сведениями, содержащимися в представленных нижестоящим налоговым органом материалах, либо несоответствия сведений, представленных налогоплательщиком, сведениям, содержащимся в материалах нижестоящего налогового органа, вышестоящий налоговый орган рассматривает жалобу (апелляционную жалобу), документы, подтверждающие доводы лица, подавшего жалобу (апелляционную жалобу), дополнительные документы, представленные в ходе рассмотрения жалобы (апелляционной жалобы), а также материалы, представленные нижестоящим налоговым органом, с участием лица, подавшего жалобу (апелляционную жалобу).\n\nРуководитель (заместитель руководителя) вышестоящего налогового органа извещает лицо, подавшее жалобу (апелляционную жалобу), о времени и месте рассмотрения жалобы (апелляционной жалобы).\n\nРассмотрение жалобы (апелляционной жалобы) возможно с использованием видео-конференц-связи в порядке, утверждаемом федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nРассмотрение жалобы (апелляционной жалобы) может быть приостановлено по решению вышестоящего налогового органа, рассматривающего жалобу (апелляционную жалобу): (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nдо разрешения дела о том же предмете и по тем же основаниям арбитражным судом, судом общей юрисдикции; (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nв случае невозможности рассмотрения жалобы (апелляционной жалобы) до разрешения другого дела судом в конституционном, гражданском, арбитражном, административном, уголовном судопроизводстве; (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nдо рассмотрения заявления о проведении взаимосогласительной процедуры в порядке, предусмотренном главой 203 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\nО принятом решении об указанном приостановлении рассмотрения жалобы (апелляционной жалобы) в течение трех дней со дня его принятия сообщается лицу, подавшему жалобу (апелляционную жалобу). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\n3. По итогам рассмотрения жалобы (апелляционной жалобы) вышестоящий налоговый орган:\n\n1) оставляет жалобу (апелляционную жалобу) без удовлетворения;\n\n2) отменяет акт налогового органа ненормативного характера;\n\n3) отменяет решение налогового органа полностью или в части;\n\n4) отменяет решение налогового органа полностью и принимает по делу новое решение;\n\n5) признает действия или бездействие должностных лиц налоговых органов незаконными и выносит решение по существу.\n\nВышестоящий налоговый орган, установив по результатам рассмотрения жалобы на решение, вынесенное в порядке, предусмотренном статьей 1014 настоящего Кодекса, нарушение существенных условий процедуры рассмотрения материалов иных мероприятий налогового контроля, вправе отменить такое решение, рассмотреть указанные материалы, документы, подтверждающие доводы лица, подавшего жалобу, дополнительные документы, представленные в ходе рассмотрения жалобы, и материалы, представленные нижестоящим налоговым органом, в порядке, предусмотренном статьей 1014 настоящего Кодекса, и вынести решение, предусмотренное пунктом 3 настоящей статьи.\n\nРешение по жалобе, не указанной в абзаце первом настоящего пункта, принимается налоговым органом в течение 15 дней со дня ее получения. Указанный срок может быть продлен руководителем (заместителем руководителя) налогового органа для получения от нижестоящих налоговых органов документов (информации), необходимых для рассмотрения жалобы, или при представлении лицом, подавшим жалобу, дополнительных документов, но не более чем на 15 дней.\n\nРешение руководителя (заместителя руководителя) налогового органа о продлении срока рассмотрения жалобы (апелляционной жалобы) вручается или направляется лицу, подавшему жалобу (апелляционную жалобу), в течение трех дней со дня его принятия.\n\nРешение налогового органа по результатам рассмотрения жалобы (апелляционной жалобы) вручается или направляется лицу, подавшему жалобу (апелляционную жалобу), в течение трех дней со дня его принятия.\n\nВ случае представления лицом, подавшим жалобу (апелляционную жалобу), дополнительных документов сроки, установленные абзацами первым и вторым настоящего пункта, исчисляются с момента получения указанных документов вышестоящим налоговым органом, рассматривающим жалобу (апелляционную жалобу). (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n(Статья в редакции Федерального закона от 02.07.2013 № 153-ФЗ)","article_title":"Статья 140. Рассмотрение жалобы (апелляционной жалобы)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bf61b2f7f5b099f4ec69b8bdcd8a61d3d1a55d0fa0c60e07028226842afeaf6f"},{"code_id":"NK_RF","article_number":"140.1","version_date":"2000-07-31","article_text":"1. Жалобы, направленные в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика в формате и в соответствии с порядком представления жалоб в электронной форме, утвержденными федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, за исключением жалоб, поданных на решения налоговых органов, принятые в соответствии со статьями 101 и 1014 настоящего Кодекса, могут быть рассмотрены в упрощенном порядке в случае указания на это в жалобе.\n\n2. Рассмотрение жалобы в упрощенном порядке осуществляется налоговым органом, акты ненормативного характера, действия или бездействие должностных лиц которого обжалуются.\n\n3. Жалоба, предусмотренная настоящей статьей, рассматривается налоговым органом в течение семи дней со дня ее получения.\n\n4. По итогам рассмотрения жалобы в соответствии с настоящей статьей налоговый орган:\n\n1) принимает решение, предусмотренное подпунктами 2 - 5 пункта 3 статьи 140 настоящего Кодекса;\n\n2) принимает меры, предусмотренные пунктом 1 или пунктами 1 и 11 статьи 139 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 31.07.2023 № 389-ФЗ)","article_title":"Статья 140.1. Особенности рассмотрения жалобы в упрощенном порядке","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f3847f0de22106c749e4f6fd722e4c703f45f25b8d529e6908f2a3b8518b397"},{"code_id":"NK_RF","article_number":"141","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 02.07.2013 № 153-ФЗ)","article_title":"Статья 141. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"47cff44cc50fb2ec2ff27049b702903fd186972de20e3143a4ff6670b28b8079"},{"code_id":"NK_RF","article_number":"142","version_date":"2000-07-31","article_text":"Жалобы (исковые заявления) на акты налоговых органов, действия или бездействие их должностных лиц, поданные в суд, рассматриваются и раз\n\nрешаются в порядке, установленном гражданским процессуальным, арбитражным процессуальным законодательством, законодательством об административном судопроизводстве и иными федеральными законами. (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\n\nРАЗДЕЛ VII1. ВЫПОЛНЕНИЕ МЕЖДУНАРОДНЫХ ДОГОВОРОВ РОССИЙСКОЙ ФЕДЕРАЦИИ ПО ВОПРОСАМ НАЛОГООБЛОЖЕНИЯ И ВЗАИМНОЙ АДМИНИСТРАТИВНОЙ ПОМОЩИ ПО НАЛОГОВЫМ ДЕЛАМ\n\n(Дополнение разделом - Федеральный закон от 27.11.2017 № 340-ФЗ)","article_title":"Статья 142. Рассмотрение жалоб, поданных в суд","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cfc57961b16fd3f4a14d2771f93dbc6e08c3cd6cda2012aeff5d46b51219ddf"},{"code_id":"NK_RF","article_number":"142.1","version_date":"2000-07-31","article_text":"Для целей настоящего Кодекса при осуществлении автоматического обмена финансовой информацией с иностранными государствами (территориями) используются следующие понятия и термины:\n\n1) международный автоматический обмен финансовой информацией с компетентными органами иностранных государств (территорий) (далее - автоматический обмен финансовой информацией) - предоставление федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, компетентным органам иностранных государств (территорий) и получение федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, от компетентных органов иностранных государств (территорий) информации, предусмотренной настоящей главой, на автоматической основе в соответствии с международными договорами Российской Федерации по вопросам налогообложения;\n\n2) организация финансового рынка - кредитная организация, страховщик, осуществляющий деятельность по добровольному страхованию жизни, профессиональный участник рынка ценных бумаг, осуществляющий брокерскую деятельность, и (или) деятельность по управлению ценными бумагами, и (или) депозитарную деятельность, управляющий по договору доверительного управления имуществом, негосударственный пенсионный фонд, акционерный инвестиционный фонд, управляющая компания инвестиционного фонда, паевого инвестиционного фонда или негосударственного пенсионного фонда, центральный контрагент, управляющий товарищ инвестиционного товарищества, иная организация или структура без образования юридического лица, которая в рамках своей деятельности принимает от клиентов денежные средства или иные финансовые активы для хранения, управления, инвестирования и (или) осуществления иных сделок в интересах клиента либо прямо или косвенно за счет клиента;\n\n3) клиент организации финансового рынка (далее - клиент) - лицо, заключающее (заключившее) с организацией финансового рынка договор, предусматривающий оказание финансовых услуг;\n\n4) финансовые услуги - услуги, связанные с привлечением от клиентов и размещением организациями финансового рынка денежных средств или иных финансовых активов для хранения, управления, инвестирования и (или) осуществления иных сделок в интересах клиента либо прямо или косвенно за счет клиента;\n\n5) финансовая информация - информация об операциях, счетах и вкладах клиентов, сумме обязательств страховщика, заключившего договор добровольного страхования жизни, перед клиентами или выгодоприобретателями, сумме денежных средств и стоимости имущества указанных лиц, находящегося в распоряжении организации финансового рынка в соответствии с договором о брокерском обслуживании или договором о доверительном управлении организации финансового рынка, стоимости имущества указанных лиц, учитываемого организацией финансового рынка, осуществляющей депозитарную деятельность, пенсионных счетах указанных лиц, обязательствах центральных контрагентов перед указанными лицами, а также о выплатах и операциях, совершенных в связи с указанными в настоящем подпункте счетами и вкладами, договором добровольного страхования жизни, договором доверительного управления имуществом (в том числе удостоверенным выдачей инвестиционного пая), договором о брокерском обслуживании, депозитарным договором, пенсионным договором, договором с центральным контрагентом и иными договорами, в рамках которых организация финансового рынка принимает от клиентов денежные средства или иные финансовые активы для хранения, управления, инвестирования и (или) осуществления иных сделок в интересах клиента либо прямо или косвенно за счет клиента;\n\n6) выгодоприобретатель - лицо (структура без образования юридического лица), к выгоде которого действует клиент, в том числе на основании агентского договора, договора поручения, договора комиссии и договора доверительного управления;\n\n7) лицо, прямо или косвенно контролирующее клиента (выгодоприобретателя) - физическое лицо, которое в конечном счете прямо или косвенно (через третьих лиц) владеет (имеет преобладающее участие более 25 процентов в капитале) клиентом (выгодоприобретателем) либо имеет возможность контролировать действия клиента (выгодоприобретателя). Лицом, прямо или косвенно контролирующим клиента (выгодоприобретателя) - физическое лицо, считается само это лицо, за исключением случаев, если имеются основания полагать, что существуют иные физические лица, прямо или косвенно контролирующие клиента (выгодоприобретателя) - физическое лицо; (В редакции Федерального закона от 29.11.2021 № 380-ФЗ)\n\n8) финансовые активы - денежные средства, ценные бумаги, производные финансовые инструменты, доли участия в уставном (складочном) капитале юридического лица или доли участия в иностранной структуре без образования юридического лица, права требования из договора страхования, а также иные активы, являющиеся предметом договора между клиентом и организацией финансового рынка, предусматривающего оказание финансовых услуг. При этом для целей настоящей главы не признаются финансовыми активами недвижимое имущество, драгоценные металлы (кроме драгоценных металлов на счетах, во вкладах или принятых для хранения с обезличением), а также ценности, принятые для хранения в индивидуальном банковском сейфе. (В редакции Федерального закона от 29.11.2021 № 380-ФЗ)","article_title":"Статья 142.1. Понятия и термины, используемые при осуществлении автоматического обмена финансовой информацией с иностранными государствами (территориями)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f75888b735050e294de1b0919536f31e9a50599abf8a52790c6d0dce4b89767"},{"code_id":"NK_RF","article_number":"142.2","version_date":"2000-07-31","article_text":"Если на основании мероприятий, установленных пунктом 1 статьи 1424 настоящего Кодекса, или имеющейся у организации финансового рынка информации не выявлены клиенты, выгодоприобретатели и (или) лица, прямо или косвенно их контролирующие, которые являются налоговыми резидентами иностранных государств (территорий), организация финансового рынка обязана представить в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, информацию о невыявлении таких клиентов, выгодоприобретателей и (или) лиц, прямо или косвенно их контролирующих. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 380-ФЗ)\n\nУказанная в абзацах первом и втором настоящего пункта информация представляется организацией финансового рынка по установленным форматам в электронной форме. Условия, порядок и сроки представления такой информации организацией финансового рынка, ее состав устанавливаются Правительством Российской Федерации по согласованию с Центральным банком Российской Федерации. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 380-ФЗ)","article_title":"Статья 142.2. Обязанности организации финансового рынка по представлению информации в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в связи с автоматическим обменом финансовой информацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0d6b9715e91b0b7d9cf36f8b06369502eba2d84ec29ea93fe780616e8211845e"},{"code_id":"NK_RF","article_number":"142.3","version_date":"2000-07-31","article_text":"1. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, в связи с осуществлением автоматического обмена финансовой информацией получает от организации финансового рынка информацию о клиентах, выгодоприобретателях и (или) лицах, прямо или косвенно их контролирующих, а также иную информацию, представляемую в соответствии с настоящей главой.\n\nФедеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, передает такую информацию компетентным органам иностранных государств (территорий), включенных в перечень государств (территорий), с которыми осуществляется автоматический обмен финансовой информацией и налоговыми резидентами которых являются клиенты, выгодоприобретатели и (или) лица, прямо или косвенно их контролирующие.\n\nПеречень государств (территорий), с которыми осуществляется автоматический обмен финансовой информацией, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Порядок передачи финансовой информации компетентным органам иностранных государств (территорий), указанным в пункте 1 настоящей статьи, получения финансовой информации федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, от таких компетентных органов, а также требования к защите передаваемой финансовой информации определяются Правительством Российской Федерации.\n\n3. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, и территориальные налоговые органы вправе использовать финансовую информацию организаций финансового рынка и компетентных органов иностранных государств (территорий), полученную в соответствии с настоящей главой, при осуществлении своих полномочий в соответствии с законодательством Российской Федерации о налогах и сборах.\n\n4. Финансовая информация в электронной форме от организаций финансового рынка и компетентных органов иностранных государств (территорий), поступившая в федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, приравнивается к информации, полученной на бумажном носителе.","article_title":"Статья 142.3. Полномочия федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, в связи с автоматическим обменом финансовой информацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50c66503dfa766492cd7b4686c48e41b7b794edd8bd2d3a4881444bd26926394"},{"code_id":"NK_RF","article_number":"142.4","version_date":"2000-07-31","article_text":"1. В целях исполнения обязанностей, установленных настоящей главой, организация финансового рынка в порядке, установленном Правительством Российской Федерации по согласованию с Центральным банком Российской Федерации, запрашивает, обрабатывает, в том числе документально фиксирует, и анализирует полученную информацию, а также принимает, в том числе документально фиксирует, обоснованные и доступные в сложившихся обстоятельствах меры по установлению налогового резидентства клиентов, выгодоприобретателей и лиц, прямо или косвенно их контролирующих, включая проверку достоверности и полноты предоставленной клиентом информации.\n\n2. Клиенты обязаны представлять в организацию финансового рынка информацию в отношении самих себя, выгодоприобретателей и (или) лиц, прямо или косвенно их контролирующих, запрашиваемую организацией финансового рынка в соответствии с настоящей главой.\n\n3. При исполнении обязанностей, предусмотренных настоящей главой, организация финансового рынка вправе использовать имеющуюся у такой организации информацию, полученную в связи с исполнением требований законодательства Российской Федерации о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма.\n\n4. В случае непредставления лицом, заключающим с организацией финансового рынка договор, предусматривающий оказание финансовых услуг, информации, запрашиваемой в соответствии с настоящей главой, организация финансового рынка вправе отказать в заключении такого договора с этим лицом.\n\n5. В случае непредставления клиентом запрашиваемой в соответствии с настоящей главой информации организация финансового рынка вправе отказать в совершении операций, осуществляемых в пользу или по поручению клиента по договору, предусматривающему оказание финансовых услуг (далее в настоящей главе - отказ в совершении операций), и (или) в случаях, предусмотренных настоящей главой, расторгнуть в одностороннем порядке договор, предусматривающий оказание финансовых услуг, уведомив об этом клиента не позднее одного рабочего дня, следующего за днем принятия решения.\n\n6. Отказ в совершении операций означает прекращение организацией финансового рынка операций по договору, предусматривающему оказание финансовых услуг, за исключением операций, осуществляемых в целях, предусмотренных абзацами вторым - пятым пункта 2 статьи 855 Гражданского кодекса Российской Федерации, а также операций по переводу денежных средств на банковский счет клиента, открытый в другой кредитной организации, или по выдаче денежных средств клиенту.\n\nВ случае поступления денежных средств для зачисления на счет (вклад) клиента в банке после принятия организацией финансового рынка, являющейся кредитной организацией, решения об отказе в совершении операций указанные денежные средства не подлежат зачислению на счет (вклад) клиента в банке и возвращаются организацией финансового рынка, являющейся кредитной организацией, на счета плательщиков в банках-отправителях. (Дополнение абзацем - Федеральный закон от 29.11.2021 № 380-ФЗ)\n\n7. В случае непредставления клиентом в течение пятнадцати дней со дня отказа в совершении операций информации, запрашиваемой организацией финансового рынка в соответствии с настоящей главой, организация финансового рынка вправе в одностороннем порядке расторгнуть заключенный с ним договор, предусматривающий оказание финансовых услуг, с учетом положений Гражданского кодекса Российской Федерации.\n\nВ случае представления клиентом информации, запрашиваемой организацией финансового рынка, после отказа в совершении операций до момента, когда договор, предусматривающий оказание финансовых услуг, считается расторгнутым, организация финансового рынка вправе отменить принятое ранее решение о расторжении договора.\n\n8. Если в результате проведения мер, предусмотренных пунктом 1 настоящей статьи, организация финансового рынка выявит недостоверность или неполноту представленной клиентом информации либо придет к выводу о противоречии представленной клиентом информации сведениям, имеющимся в распоряжении организации финансового рынка, в том числе полученным из иных общедоступных источников информации, организация финансового рынка вправе отказать в заключении договора, предусматривающего оказание финансовых услуг, либо в одностороннем порядке расторгнуть заключенный договор, предусматривающий оказание финансовых услуг.\n\n9. Договор, предусматривающий оказание финансовых услуг, считается расторгнутым по истечении одного месяца со дня направления организацией финансового рынка клиенту уведомления о расторжении договора, предусматривающего оказание финансовых услуг, если иной срок не установлен договором, предусматривающим оказание финансовых услуг.","article_title":"Статья 142.4. Обязанности и права организаций финансового рынка и их клиентов в связи с автоматическим обменом финансовой информацией","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fce876b02381807bf92a70debc3574bd24910e0cde7a9652191e2b6630cd919"},{"code_id":"NK_RF","article_number":"142.5","version_date":"2000-07-31","article_text":"1. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, вправе передавать страновые отчеты, полученные согласно положениям главы 144-1 настоящего Кодекса, компетентным органам иностранных государств (территорий) в рамках автоматического обмена страновыми отчетами в соответствии с международными договорами Российской Федерации. Перечень иностранных государств (территорий), с компетентными органами которых осуществляется автоматический обмен страновыми отчетами, утверждается федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n2. Федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, принимает, обрабатывает, хранит и использует при осуществлении своих полномочий по контролю и надзору страновые отчеты, полученные от компетентных органов иностранных государств (территорий) в рамках автоматического обмена страновыми отчетами в соответствии с международными договорами Российской Федерации.\n\n3. Порядок передачи страновых отчетов компетентным органам иностранных государств (территорий), получения страновых отчетов федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, от компетентных органов таких государств (территорий), а также требования к защите передаваемой информации, содержащейся в страновых отчетах, устанавливаются Правительством Российской Федерации.","article_title":"Статья 142.5. Полномочия федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, при осуществлении автоматического обмена страновыми отчетами","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3af9908b259c3ba719c24275295b279eff16ae4228c95a4ace89a88e6ab36f0a"}]$law7d0054$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
